private void Shoot()
{
    var bullet = _bulletScene.Instantiate<Node2D>();
    bullet.GlobalPosition = GlobalPosition;
    GetTree().CurrentScene.AddChild(bullet);

    #if DEBUG
    GD.Print($"Spawned bullet at {GlobalPosition}");
    #endif
}

